update goods
set stock=stock - #{i}
where goods.id = #{goodsId}

update orders
set status=#{param2}
where id = #{param1}

update orders
set status=2,
    get_time=#{param2}
where id = #{param1}

mapper.select:
select orders.id as orderId, orders.time, orders.type, orders.status, orders.get_time, orders.payment_price , orders.num, orders.order_string , goods.id as goodsId , goods.name as goodsName , goods.images , goods.sort_introduce, address.*, `user`.id as userId, `user`.headimg_url, `user`.name as userName from orders , goods , address , `user` where orders.goods_id = goods.id and orders.address_id = address.id and orders.address_id = address.id and `user`.id = address.user_id
and goods.class_id=#{listVto.classId}
and goods.name like CONCAT('%',#{listVto.likeName},'%')
and `user`.phone like CONCAT('%',#{listVto.phone},'%')
and `user`.name like CONCAT('%',#{listVto.userName},'%')
and orders.order_string=#{listVto.orderString}

select count(*)
from orders
where user_id = #{param1}
  and `status` = #{param2}

select orders.id as orderId, orders.time, orders.type, orders.status, orders.get_time, orders.payment_price , orders.num, goods.id as goodsId , goods.name as goodsName , goods.images, address.*, `user`.id as userId from orders , goods , address , `user` where orders.goods_id = goods.id and orders.address_id = address.id and orders.address_id = address.id and `user`.id = address.user_id and `user`.id=#{orderPageVto.userId}
and orders.status=#{orderPageVto.status}
order by orders.`status` desc
